/* Месяцеслов «Православных» — 06.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M06: SaintRec[] = [
  { key: "06-01", name: "День Святого Духа", kind: "feast", desc: "В следующий за Пятидесятницей день, то есть в понедельник, совершается праздник в честь Святого Духа (потому сам день иногда называется «понедельник Святого Духа»)." },
  { key: "06-01", name: "прп. Корнилия Комельского, чудотворца", kind: "saint", desc: "Происходил из боярского рода, в юности ушел в монастырь. Стремясь к уединению, переходил из обители в обитель, пока в 1497 г. не поселился в Комельском лесу под Вологдой." },
  { key: "06-01", name: "блгв. вел. кн. Димитрия Донского", kind: "saint", desc: "Великий князь Московский с 9 лет. Воспитывался свт. Алексием Московским. Объединил русские земли для борьбы с Ордой. Главные подвиги: победа на Куликовом поле (1380) над Мамаем после благословения прп." },
  { key: "06-01", name: "и прп. Евфросинии, в миру Евдокии, вел. кн. Московской", kind: "saint", desc: "Супруга блгв. кн. Дмитрия Донского. С юных лет отличалась глубоким благочестием. Во время Куликовской битвы молилась за победу русского войска, а после победы построила в Кремле храм Рождества Пресвятой Богородицы." },
  { key: "06-01", name: "Прп. Корнилия, игумена Палеостровского, Олонецкого", kind: "saint", desc: "Родом из Пскова, принял монашество в зрелом возрасте. Подвижничество начал на Валааме, затем просвещал язычников Поморья, странствовал по пустыням. Ок." },
  { key: "06-01", name: "блгв. кн. Иоанна Угличского, в иночестве Игнатия, Вологодского", kind: "saint", desc: "Сын блгв. кн. Андрея Угличского. В 13 лет с братом Димитрием невинно заключен в темницу по приказу дяди — вел. кн. Иоанна III. Провел 32 года в заточении (1491–1523), перенося узы с молитвой и утешая брата." },
  { key: "06-01", name: "прп. Сергия Шухтомского", kind: "saint", desc: "Схимник Шухтомской пустыни под Череповцом. Родился в Казани, в младенчестве питался ячменным суслом (как прп. Сергий Радонежский). Совершил 3-летнее паломничество: Палестина, Константинополь, Афон, Соловки." },
  { key: "06-01", name: "мч. Калуфа Египтянина", kind: "saint", desc: "Египетский мученик (†303) времён гонений Максимиана. За веру был повешен вниз головой с камнем на шее, но повторял: «Всё терплю ради будущего блаженства»." },
  { key: "06-01", name: "прп. Иоанна, епископа Готфского", kind: "saint", desc: "Был рукоположен во епископа Готфии в Грузии (Иверии). Принимал участие в VII Вселенском Соборе (787 г.), восстановившем иконопочитание. Вернувшись в епархию, изгнал хазар из столицы Дори, но был захвачен ими и заключён в темницу." },
  { key: "06-01", name: "Собор святых Белгородской митрополии", kind: "feast", desc: "Собор святых Белгородской митрополии – празднование Русской Православной Церкви в честь святых Белгородской земли. Поименный список собора святых Белгородской митрополии утвержден решением Священного Синода 24 июля 2025 года (журнал № 69)." },
  { key: "06-01", name: "Матфия Вознесенского", kind: "saint", desc: "Сын дьячка из Курской губернии. Окончил Белгородскую семинарию (1883). 35 лет служил священником в слободе Фощеватое: строил храмы, обучал детей, был благочинным." },
  { key: "06-01", name: "Виктора Каракулина (1937), пресвитеров", kind: "saint", desc: "Сын псаломщика из Курской губернии. Окончил Курскую духовную семинарию (1909). Рукоположен во священника в 1910 г., служил в Троицком храме Курска. 23 июля 1935 г." },
  { key: "06-01", name: "прмч. Валентина (Лукьянова), иеромонаха", kind: "saint", desc: "Родился в Калужской губернии, в миру — Василий. Овдовев, в 1906 г. поступил в Троице-Сергиеву Лавру послушником. В 1915 г. пострижен в монашество. Обладал выдающимися певческими дарованиями." },
  { key: "06-01", name: "Кипрская", year: "392", kind: "saint", desc: "Кипрская икона Божией Матери явилась в 392 году на острове Кипре на месте, где был погребен праведный Лазарь, и была помещена в монастыре Ставруни, устроенном на месте ее чудесного обретения." },
  { key: "06-02", name: "Обретение мощей свт. Алексия, митрополита Киевского, Московского и всея Руси, чудотворца", kind: "saint", desc: "Родился в Москве в семье боярина. В 12 лет услышал голос Божий: «Алексий! Ты будешь ловить людей». Принял постриг в Богоявленском монастыре, где провёл 20 лет в подвижничестве." },
  { key: "06-02", name: "Блгв. кн. Довмонта, во Святом Крещении Тимофея, Псковского", kind: "saint", desc: "Литовский князь, изгнанный с родины и нашедший приют в Пскове, где был избран правителем в 1266 году. Приняв православие, укрепил город каменной стеной, защищал Псков от немцев и литовцев." },
  { key: "06-02", name: "мч. Аскалона Антинойского", kind: "saint", desc: "Христианин из Ермополя, пострадал при Диоклетиане. Смело исповедал веру перед правителем Аррианом, предрек ему: «Сам назовешь Христа Истинным Богом». После жестоких пыток (подвешивание, терзание железом) остался непоколебим." },
  { key: "06-02", name: "Сщмч. Павла Лазарева, пресвитера", kind: "saint", desc: "Сибиряк из Колывани, бывший фельдшер. Рукоположен во священника в 1915 г., служил в селе Антоновка Приморья. Помогал бедным, учил детей Закону Божию. В канун Пятидесятницы 1919 г." },
  { key: "06-03", name: "Владимирской иконы Божией Матери", kind: "icon", desc: "Владимирская икона Божией Матери написана Евангелистом Лукой на доске от стола, за которым трапезовал Спаситель с Пречистой Матерью и праведным Иосифом." },
  { key: "06-03", name: "царя Константина", kind: "saint", desc: "Римский император, прекративший гонения на христиан Миланским эдиктом (313 г.). Перед решающей битвой увидел на небе знамение Креста с надписью «Сим побеждай»." },
  { key: "06-03", name: "св. царицы Елены", kind: "saint", desc: "Мать равноап. императора Константина Великого. В 80 лет совершила паломничество в Иерусалим, где по её указанию начались раскопки на Голгофе. В 326 году чудесным образом обрела Животворящий Крест Господень." },
  { key: "06-03", name: "Обретение мощей блж. Андрея Симбирского", kind: "saint", desc: "Родился в мещанской семье, с 7 лет избрал подвиг юродства: питался лишь хлебом и ягодами, общался жестами. Ночью молился у стен Вознесенского собора, целуя его ограду." },
  { key: "06-03", name: "Прп. Кассиана грека, Угличского, Учемского, чудотворца", kind: "saint", desc: "Потомок греческих князей, прибыл в Москву с царевной Софией Палеолог (1478). Отказавшись от придворной жизни, ушёл в Ферапонтов монастырь, где принял постриг." },
  { key: "06-03", name: "Собор Карельских святых", kind: "feast", desc: "В 1910 году преосвященный Никанор, епископ Олонецкий и Петрозаводский благословил написание первой иконы Собора Карельских святых. Икона была написана, и ее снимок опубликован в газете «Олонецкие епархиальные ведомости»." },
  { key: "06-03", name: "Собор Симбирских святых", kind: "feast", desc: "Текст службы утвержден к общецерковному богослужебному употреблению на заседании Священного Синода 29 декабря 2022 года (журнал № 130). Духа Святаго благодать/ в тебе излияся, отче Гаврииле,/ темже пастырь добрый/ Церкве Христовы явился еси" },
  { key: "06-03", name: "Собор Уфимских святых", kind: "feast", desc: "Недавно был создан Собор Уфимских святых – туда вошли 12 подвижников, которые когда-то жили в Башкирии. Большая часть из них погибла в период становления советской власти – святых расстреливали за контрреволюционную агитацию." },
  { key: "06-03", name: "Умиление Псково-Печерская", year: "1524", kind: "saint", desc: "По преданию, Псково-Печерская икона Божией Матери «Умиление» была написана в 1521 году неким иеромонахом Арсением (Хитрошем) с иконы Божией Матери «Владимирская»." },
  { key: "06-03", name: "Владимирская (Заоникиевская)", year: "1588", kind: "saint", desc: "Эта Владимирская икона явилась в 1588 году в 12 верстах от Вологды вологодскому поселянину Илариону – будущему преподобному Иосифу Заоникиевскому – при следующих обстоятельствах." },
  { key: "06-03", name: "Владимирская (Красногорская, Черногорская)", year: "1603", kind: "saint", desc: "Красногорская (Черногорская) Владимирская икона Божией Матери известна с 1603 года. Игумен Варлаам, служивший в храме Воскресения Христова в Кевроле, на реке Пинеге, имел у себя список с Владимирской иконы Божией Матери." },
  { key: "06-03", name: "Владимирская (Оранская)", year: "1634", kind: "saint", desc: "Оранская Владимирская икона Божией Матери явилась в 1634 году при следующих обстоятельствах: нижегородский вотчинник Петр Гладков питал глубокое благоговение к Владимирской иконе Божией Матери, находившейся в Московском Успенском соборе." },
  { key: "06-04", name: "Мч. Василиска Команского", kind: "saint", desc: "Племянник св. Феодора Тирона. По пути на казнь в медных сапогах с гвоздями (которые вонзались при шаге) молился у сухого дерева — произошло землетрясение, и из скалы забил источник." },
  { key: "06-04", name: "мч. Иоанна-Владимира, кн. Сербского", kind: "saint", desc: "Князь Зеты (Черногория), мудрый и милостивый правитель. Прославился благочестием: строил храмы, молился ночами, боролся с ересью богомилов. Защищал землю от захватчиков." },
  { key: "06-04", name: "прав. Иакова Боровичского, Новгородского чудотворца", kind: "saint", desc: "Сведений о жизни не сохранилось. Прославился посмертно: в 1540-х годах его гроб на льдине трижды приплывал против течения к селу Боровичи (Новгородчина)." },
  { key: "06-04", name: "Память II Вселенского Собора", year: "381", kind: "feast", desc: "Второй Вселенский Собор состоялся в 381 году и довершил победу православия, одержанную в 325 году на Первом Вселенском Соборе. В трудные годы, протекшие после принятия Никейского Символа веры, арианская ересь дала новые побеги." },
  { key: "06-04", name: "Сщмч. Максима (Жижиленко), епископа Серпуховского", kind: "saint", desc: "Врач-психиатр, главный врач тюремной больницы в Москве. Тайно принял монашество (1925), рукоположен во епископа Серпуховского в катакомбной церкви (1928)." },
  { key: "06-04", name: "сщмч. Михаила Борисова, пресвитера", kind: "saint", desc: "Священник из Новгородской губернии. Активный пастырь: служил в разных приходах, был законоучителем, благочинным. Открыто выступал против советской власти за гонения на Церковь." },
  { key: "06-04", name: "«Споручница грешных» Корецкая", year: "1622", kind: "saint", desc: "Древняя икона Божией Матери «Споручница грешных» Корецкая издревле хранилась в замке корецких князей и именовалась «благодатной». После гибели последнего из православных корецких князей Самуила, его брат Иоанн предложил своей сестре игумени" },
  { key: "06-05", name: "Прп. Михаила исп., епископа Синадского (Фригийского)", kind: "saint", desc: "С юности монах, стал епископом Синадским. Прославился святой жизнью, присутствовал на VII Вселенском Соборе (787 г.). Когда к власти пришел иконоборец Лев Армянин (813 г.), начавший гонения на православие, святитель Михаил мужественно выступил в защиту иконопочитания." },
  { key: "06-05", name: "Обретение мощей свт. Леонтия, епископа Ростовского", kind: "saint", desc: "Святитель Леонтий, первый русский епископ из Киево-Печерского монастыря (XI в.), просветитель Ростовской земли. Столкнувшись с враждебностью язычников, изгнавших его предшественников, он поселился у Ростова, проповедовал и крестил сначала детей, затем взрослых." },
  { key: "06-05", name: "Собор Ростово-Ярославских святых", kind: "feast", desc: "Установлен 10 марта 1964 года по инициативе архиепископа Ярославского и Ростовского Никодима (Ротова) решением патриарха Московского и всея Руси Алексия I и Священного Синода Русской Православной Церкви." },
  { key: "06-05", name: "Преподобной Евфросинии, игумении Полоцкой", kind: "saint", desc: "Княжна, с юности посвятила жизнь Богу. Отказавшись от брака, приняла постриг. По благословению епископа Илии, основала в Полоцке Спасо-Преображенский женский монастырь." },
  { key: "06-05", name: "прп. Паисия Галичского, архимандрита", kind: "saint", desc: "Игумен Успенского монастыря под Галичем. Подвизался в обители более 70 лет, восстанавливая её после междоусобиц. Прославился дипломатической миссией: по просьбе князя отвез список чудотворной Овиновской иконы Божией Матери в Москву (после её чудесного возвращения в монастырь из столицы)." },
  { key: "06-05", name: "прмч. Михаила Савваита, черноризца", kind: "saint", desc: "Ученик святого Феодора Эдесского. Раздав имущество, отправился в Иерусалим, поселился в лавре св. Саввы. При продаже монастырских изделий попал к мусульманской царице Сеиде." },
  { key: "06-05", name: "Обретение мощей мцц. Евдокии Шейковой", kind: "saint", desc: "Крестьянка из с. Пуза (ныне Суворово) Нижегородской губ. С 20 лет, будучи парализованной, вела строгую молитвенную жизнь, неся подвиг юродства. Обладала даром прозорливости и исцелений." },
  { key: "06-05", name: "Дарии Тимагиной", kind: "saint", desc: "Крестьянка из Нижегородской губ. В 15 лет, несмотря на противодействие родителей (дважды сбегала от насильной выдачи замуж), стала келейницей парализованной подвижницы Евдокии Шейковой." },
  { key: "06-05", name: "Дарии Улыбиной", kind: "saint", desc: "Келейница св. Евдокии Шейковой в с. Пуза (ныне Суворово) Нижегородской губ. С 1916 года подвизалась у парализованной наставницы, отличаясь смирением и благочестием." },
  { key: "06-05", name: "Марии Неизвестной", kind: "saint", desc: "Одна из 3-х келейниц мц. Евдокии Шейковой в с. Пуза (Нижегородская губ.). 18 августа 1919 г., когда Евдокию приговорили к расстрелу по ложному обвинению, Мария добровольно избрала смерть вместе с наставницей и сёстрами (Дариями Улыбиной и Тимагиной)." },
  { key: "06-06", name: "Отдание праздника Пятидесятницы", kind: "feast", desc: "Христианская Пятидесятница имеет свой ветхозаветный прототип — одноименный иудейский праздник &Pi;&epsilon;&nu;&tau;&eta;&kappa;&omicron;&sigma;&tau;ή — Пятидесятница." },
  { key: "06-06", name: "Прп. Симеона Столпника на Дивной горе, пресвитера", kind: "saint", desc: "Столпник VI века. С детства избран Богом: ему являлся Христос, предсказавший подвиги. В 6 лет удалился в пустыню, позже взошёл на столп в обители св. Иоанна Столпника." },
  { key: "06-06", name: "прп. Никиты, столпника Переяславского", kind: "saint", desc: "В миру жестокий сборщик податей. Покаялся, услышав слова пророка Исаии в храме, и увидев кипящие человеческие члены в котле (символ его грабежа). Ушел в монастырь св." },
  { key: "06-06", name: "блж. Ксении Петербургской", kind: "saint", desc: "Блж. Ксения Петербургская (ок. 1720–1803), молодая вдова, избрала подвиг юродства Христа ради, чтобы вымолить душу внезапно умершего мужа. Раздав имущество, ходила в его одежде, утверждая, что \"умерла Ксения\".", lifeId: "kseniya" },
  { key: "06-06", name: "Явление чудотворного образа Спаса Нерукотворенного во граде Ярославле", year: "1612", kind: "feast", desc: "Празднование явления в Ярославле чудотворного образа Спаса Нерукотворного внесено в месяцеслов по благословению Священного Синода Русской Православной Церкви 17 июня 2021 года." },
  { key: "06-06", name: "прп. Викентия Леринского", kind: "saint", desc: "Галльский аристократ, оставивший мир ради монашества в обители Лерина (Франция). Прославился ученостью и святостью жизни. Около 434 г. написал трактат «Напоминание» (Commonitorium), ставший ключевым для Православия." },
  { key: "06-07", name: "Третье обр е тение главы Пророка, Предтечи и Крестителя Господня Ио а нна", year: "ок. 850", kind: "feast", desc: "Пророк Иоанн Креститель – после Девы Марии самый чтимый святой. С именем Иоанна Предтечи связано семь праздников (по новому стилю). Пророк Иоанн Креститель был сыном священника Захарии (из рода Аарона) и праведной Елизаветы (из рода царя Давида).", lifeId: "ioann-predtecha" },
  { key: "06-07", name: "Свт. Иннокентия (Борисова), архиепископа Херсонского", kind: "saint", desc: "Великий проповедник («Русский Златоуст»), богослов и архипастырь. Родился в Ельце, сын священника. Блестяще окончил Киевскую академию. Был выдающимся профессором и ректором." },
  { key: "06-07", name: "сщмч. Ферапонта, епископа Кипрского", kind: "saint", desc: "Пострадал за Христа во время гонений императора Диоклитиана (284–305 гг.). После мученической кончины его мощи пребывали на Кипре, прославившись чудесами." },
  { key: "06-07", name: "Собор мучеников Холмских и Подляшских", kind: "feast", desc: "В 2003 году автокефальная Православная Церковь в Польше прославила в лике святых новых мучеников. Когда, казалось бы, православие в этих землях почти уничтожено, православный мир становится свидетелем одного из значительных событий в церковной истории – причисление к лику святых мучеников Холмских и Подляшских." },
  { key: "06-07", name: "Прмц. Елены (Коробковой), инокини", kind: "saint", desc: "Приняла монашество в одном из монастырей Московской губернии. После его закрытия в годы гонений поселилась при Троицкой церкви в г. Сходня: пела на клиросе и шила одеяла на пропитание." },
  { key: "06-07", name: "прмч. Тавриона (Толоконцева), монаха", kind: "saint", desc: "Родился в Вологодской губернии. Принял монашество в 1920 году в Валаамском монастыре. После закрытия подворья в Москве (1925) служил певчим в Ржевской церкви, где монахи создали тайную общину." },
  { key: "06-07", name: "Умягчение злых сердец", kind: "saint", desc: "Икону Божией Матери «Умягчение злых сердец» называют еще «Симеоново проречение». Как повествует святой евангелист Лука, праведному старцу Симеону Богоприимцу «...было предсказано Духом Святым, что он не увидит смерти, доколе не увидит Христа Господня» ( Лк.2:26 )." },
  { key: "06-07", name: "Нерушимая Стена", kind: "saint", desc: "Чудотворная икона Пресвятой Богородицы «Нерушимая Стена» выполнена в стиле мозаики на стене над горним местом главного алтаря киевского Софийского собора ." },
  { key: "06-08", name: "Апп. от 70-ти Карпа и Алфея", year: "I", kind: "saint", desc: "Память святых апостолов от 70-ти Карпа и Алфея совершается 8 июня." },
  { key: "06-08", name: "мч. Георгия Нового", kind: "saint", desc: "Знатный болгарин из г. Средце (ныне София). Открыто исповедовал христианство под турецким игом. За отказ принять ислам был схвачен. Паша, пораженный его мужеством, тщетно сулил богатство.", lifeId: "georgiy" },
  { key: "06-08", name: "Обретение мощей прп. Макария, игумена Калязинского", kind: "saint", desc: "В миру Матфей Кожин — сын боярина. Овдовев, принял постриг. Около 1434 г. ушёл в пустынное место близ Калязина, где основал обитель во имя Святой Троицы (будущий Калязинский Макариев монастырь), став в ней первым игуменом." },
  { key: "06-08", name: "прп. Иоанна Психаита, исп.", kind: "saint", desc: "Монах Психаитской Лавры (Константинополь), исповедник. Обладал даром чудотворений. В гонение иконоборцев отказался отречься от почитания икон. На допросе обличил императора Льва Исавра как еретика." },
  { key: "06-09", name: "Сщмч. Ферапонта, епископа Сардийского", kind: "saint", desc: "Епископ г. Сарды (Лидия, Малая Азия). Обратил в христианство множество язычников, за что предстал перед правителем Юлианом. После отказа отречься его бросили в темницу, морили голодом, жестоко пытали в Сардах, Синаоне и Анкире." },
  { key: "06-09", name: "Обретение мощей прп. Нила Столобенского", kind: "saint", desc: "Крестьянин из Новгородской земли, принял постриг в Крыпецком монастыре. После 10 лет в обители удалился в пустынь на реку Серемлю, затем по Божественному указанию поселился на острове Столобный на озере Селигер." },
  { key: "06-09", name: "Прп. Ферапонта Белоезерского, Можайского, архимандрита", kind: "saint", desc: "В миру Феодор Поскочин — дворянин из Волоколамска. Принял постриг в 40 лет в Московском Симоновом монастыре, где сдружился с прп. Кириллом Белозерским." },
  { key: "06-09", name: "Перенесение мощей свтт. Московских Киприана", kind: "saint", desc: "Серб (или болгарин), афонский монах. В 1375 г. поставлен митрополитом Киевским и всея Руси, управляя юго-западной частью Церкви. С 1390 г. – объединил кафедру в Москве." },
  { key: "06-09", name: "прп. Ферапонта Монзенского", kind: "saint", desc: "Начал подвижничество в Москве, возможно, как юродивый. Принял постриг в Костромском Воздвиженском монастыре, где прожил 13 лет. Позже явился во сне инокам Пафнутию и Андриану, повелев основать Благовещенский монастырь на реке Монзе." },
  { key: "06-09", name: "прав. Иоанна Русского, исп.", kind: "saint", desc: "Уроженец Малороссии, солдат Петра I. Попал в турецкий плен во время Прутского похода (1711 г.). Продан в рабство командиру. Сохранял веру Христову в мусульманской среде: молился тайно, переносил насмешки и угрозы." },
  { key: "06-10", name: "Прп. Никиты исп., епископа Халкидонского", kind: "saint", desc: "Прп. Никита Халкидонский (VIII–IX вв.) — епископ, исповедник, известный милосердием: помогал нищим, сиротам, защищал обижаемых. При иконоборце Льве Армянине (813–820) смело обличал ересь, за что был заточен и умер в ссылке." },
  { key: "06-10", name: "свт. Игнатия, епископа Ростовского", kind: "saint", desc: "Просветитель Ростовской земли (XIII в.). Активно боролся с язычеством. Основал монастырь в честь Богоявления. Прославился чудесами: по преданию, остановил пожар в Ростове молитвой." },
  { key: "06-10", name: "прп. Елены Дивеевской (Мантуровой)", kind: "saint", desc: "Одна из первых сестер Дивеевской обители, духовная дочь прп. Серафима Саровского. Отказалась от дворянской жизни, приняла подвиг юродства и служила Богу в смирении и молитве." },
  { key: "06-10", name: "Свт. Геронтия, митрополита Московского и всея Руси", kind: "saint", desc: "Святитель Геронтий, митр. Московский и всея Руси († 1489) – выдающийся церковный деятель эпохи становления русского централизованного государства. Возглавлял Русскую Церковь в 1473-1489 годах." },
  { key: "06-10", name: "сщмч. Евтихия, епископа Мелитинского", kind: "saint", desc: "Священномученик Евтихий, епископ Мелитинский, сотрудник святых апостолов, пострадал за Христа в городе Мелитине в I веке. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите тек" },
  { key: "06-10", name: "мц. Еликониды Солунской (Фессалоникийской)", kind: "icon", desc: "Мученица III века. Приняла крещение, несмотря на языческое окружение. За открытое исповедание веры была схвачена и претерпела жестокие пытки, включая раскалённое железо и кипящую смолу." },
  { key: "06-10", name: "свт. Германа, епископа Парижского", kind: "saint", desc: "Епископ Парижа. Происходил из знатного рода, но избрал монашеский путь. Основал аббатство Сен-Жермен-де-Пре, ставшее центром духовной жизни. Прославился милосердием: выкупал пленных, помогал бедным." },
  { key: "06-10", name: "сщмч. Елладия, епископа Восточного", kind: "saint", desc: "Епископ IV века, участник I Вселенского собора (325 г.), борец с арианством. Принял мученическую смерть за веру: был схвачен арианами, подвергнут пыткам и казнён." },
  { key: "06-10", name: "Макария (Моржова), иеромонаха", kind: "saint", desc: "Уроженец Вологодской губ. После военной службы и работы в Москве в 1899 г. ушёл в Смоленскую Зосимову пустынь (Владимирская губ.), приняв постриг. Был келейником старца Алексия (Соловьёва) — участника избрания Патриарха Тихона." },
  { key: "06-10", name: "Дионисия (Петушкова), схимонаха", kind: "saint", desc: "Уроженец Тверской губернии. В 1905 г. поступил в Нило-Столобенскую пустынь, впоследствии принял схиму. После закрытия монастыря (1927) поселился на хуторе Черенчиха, где принимал страждущих." },
  { key: "06-10", name: "сщмч. Николая Аристова, диакона", kind: "saint", desc: "Дворянин из Тульской губернии, бывший фотограф. После смерти жены и младшего ребенка посвятил жизнь Церкви. В 1930 г. рукоположен во диакона Петропавловского храма в Загорске (Сергиев Посад)." },
  { key: "06-10", name: "Игнатия Маркова", kind: "saint", desc: "Крестьянин из Владимирской губернии, отец 7-х детей. В 1931 г. раскулачен (конфисковано имущество за неуплату непосильного налога). Приехав в Загорск помолиться в Троице-Сергиевой Лавре, был арестован 6 апреля 1931 г." },
  { key: "06-10", name: "Петра Юдина", kind: "saint", desc: "Плотник из Тверской губернии, помощник церковного старосты села Бокланово. В марте 1931 г. был направлен общиной в Москву закупить церковные свечи. По дороге в Хотьково в разговоре с рабочим высказался: «Власти живут в роскоши, а народ голодает." },
  { key: "06-10", name: "прп. Ираклия (Мотяха) исп., схимонаха", kind: "saint", desc: "Родился в Черниговской губернии. В 1882 г. поступил в Свято-Троицкий Иссык-Кульский монастырь, где принял постриг. Во время кыргызского восстания 1916 г." },
  { key: "06-11", name: "Прмц. Феодосии девы", kind: "saint", desc: "Прмц. Феодосия (VIII в.) воспитывалась в монастыре св. Анастасии после смерти родителей. Раздав оставшееся имущество бедным, она приняла постриг. При императоре-иконоборце Льве Исавре лжепатриарх Анастасий приказал снять образ Спасителя с медных ворот Константинополя." },
  { key: "06-11", name: "блж. Иоанна, Христа ради юродивого, Устюжского", kind: "saint", desc: "Блаженный Иоанн Устюжский родился в благочестивой семье, с юности вёл аскетичную жизнь, питаясь лишь хлебом и водой. После переселения в Орлец, а затем в Устюг, он принял подвиг юродства: ночи проводил в молитве, а днём ходил по городу в рубище, терпя насмешки." },
  { key: "06-11", name: "прп. Иова, в схиме Иисуса, Анзерского", kind: "saint", desc: "Преподобный Иов (в схиме Иисус) Анзерский родился в 1635 году в Москве, стал священником и славился благочестием, милосердием и даром молитвы. Став духовником Петра I, был оклеветан и сослан на Соловки, где принял монашество." },
  { key: "06-11", name: "Явление Честного и Животворящего Креста Господня близ града Ростова Великого на Сахотском болоте", kind: "saint", desc: "Согласно летописным сведениям около 1423 года на Сахотском болоте в Ростовских пределах произошло чудесное явление образа Животворящего Креста Господня и образа чудотворца Николая Мирликийского, сошедших с неба." },
  { key: "06-11", name: "Мц. Феодосии девы, Тирской", kind: "saint", desc: "Св. мц. Феодосия Тирская пострадала в 307 году. Во время гонений 17-летняя девушка подошла к христианским узникам в претории в Пасхальный день, прося помянуть её перед Господом." },
  { key: "06-11", name: "Память I Вселенского Собора", year: "325", kind: "feast", desc: "Память Первого Вселенского Собора празднуется Церковью Христовой с древнейших времен. Господь Иисус Христос оставил Церкви великое обетование: «Создам Церковь Мою, и врата ада не одолеют Ее» ( Мф.16:18 )." },
  { key: "06-11", name: "Собор святых Красноярской митрополии", kind: "feast", desc: "Собор святых Красноярской митрополии учрежден в 2015 году по благословению Святейшего Патриарха Московского и всея Руси Кирилла. Днем празднования Собора установлено 11 июня (29 мая), день памяти святителя Луки (Войно-Ясенецкого)." },
  { key: "06-11", name: "Сщмч. Иоанна Преображенского, протодиакона", kind: "saint", desc: "Священномученик Иоанн Преображенский (1880-1938) родился в семье псаломщика, служил диаконом в Вологде. В 1937 году активно защищал Богородское кладбище и храм от закрытия, собирая подписи прихожан." },
  { key: "06-11", name: "мч. Андрея Трофимова", kind: "saint", desc: "Мученик Андрей Трофимов (1882-1938), крестьянин из Подмосковья, с юности был активным прихожанином, регентом и членом церковного совета. В 1930-х годах, работая в колхозе, отказывался трудиться в церковные праздники, призывая односельчан посещать храм." },
  { key: "06-11", name: "свт. Луки (Войно-Ясенецкого), исп., архиепископа Симферопольского и Крымского", kind: "saint", desc: "Свт. Лука (Войно-Ясенецкий, 1877–1961) – архиепископ, выдающийся хирург и профессор медицины. Родился в Керчи. Сочетал врачебную практику с пастырским служением." },
  { key: "06-11", name: "Споручница грешных", kind: "saint", desc: "Икона Божией Матери &quot;Споручница грешных&quot; названа так по надписи, сохранившейся на иконе: &quot;Аз Споручница грешных к Моему Сыну...&quot;. Впервые этот образ прославился чудесами в Николаевском Одрине мужском монастыре Орловской губернии в середине 19-го столетия." },
  { key: "06-11", name: "Недремлющее Око", kind: "saint", desc: "В городе Рыбинске, в монастырской часовне, устроенной недалеко от вокзала Рыбинско-Бологовской железной дороги, находится древняя чудотворная икона, именуемая «Недремлющее око»." },
  { key: "06-12", name: "Прп. Исаакия исп., игумена обители Далматской", kind: "saint", desc: "Св. Исаакий Далматский жил в IV веке, был монахом и основателем Далматского монастыря под Константинополем. Прославился обличением ереси арианства и смелым противостоянием императору-еретику Валенту." },
  { key: "06-12", name: "прп. Варлаама Хутынского (1192)", kind: "saint", desc: "Прп. Варлаам Хутынский (XII в.) был сыном знатного новгородца. Оставив мирскую жизнь, он поселился в уединённом месте Хутынь близ Новгорода, где вёл суровую подвижническую жизнь." },
  { key: "06-12", name: "Собор святых Пензенской митрополии", kind: "feast", desc: "17 июля 2020 года митрополит Пензенский и Нижнеломовский Серафим обратился с рапортом к Святейшему Патриарху Московскому и всея Руси Кириллу. В нем он, согласно решению Архиерейского совета Пензенской митрополии, просил благословения на поч" },
  { key: "06-12", name: "Сщмч. Василия Смоленского, пресвитера", kind: "saint", desc: "Священномученик Василий Смоленский (1869–1942) родился в семье псаломщика, окончил Московскую духовную семинарию и в 1891 году был рукоположен во священника." },
  { key: "06-12", name: "Табынская", kind: "saint", desc: "Табынская икона Божией Матери – самая загадочная икона в России. Табынскую икону можно назвать даже сверхчудотворной. По многим местам в России можно натолкнуться на смутные воспоминания о ней, а порой легендарные сказания." },
  { key: "06-12", name: "Знамение Курская-Коренная", kind: "saint", desc: "Курская икона «Знамение» Божией Матери — одна из древнейших икон Русской Церкви. В ХIII веке, во время татарского нашествия, когда все Русское государство испытывало величайшее бедствие, город Курск, разоренный полчищами Батыя, пришел в запустение." },
  { key: "06-13", name: "Ап. от 70-ти Ерма", kind: "saint", desc: "Св. апостол Ермий, упомянутый в Рим.16:14, почитается как просветитель Далмации. Согласно церковному преданию, он обращал местных жителей от язычества, совершая чудеса и исцеления." },
  { key: "06-13", name: "мч. Ермия Команского", kind: "saint", desc: "Св. мученик Ермий, пожилой воин, пострадал в Команах Каппадокийских при императоре Антонине Пии (138-161 гг.). Отказавшись принести жертву идолам, он перенес жестокие пытки: его лицо лишили кожи, бросали в раскаленную печь (где остался невр" },
  { key: "06-13", name: "Мч. Философа Александрийского", kind: "saint", desc: "Пострадал в Александрии при императоре Декии (249-251 гг.). Юношу пытались склонить к отречению от Христа, но он остался тверд. Чтобы избежать греха с подосланной женщиной, он откусил себе язык, выплюнув его в лицо искусительнице." },
  { key: "06-14", name: "прп. Дионисия, игумена Глушицкого", kind: "saint", desc: "Прп. Дионисий Глушицкий (1362-1437) родился под Вологдой, с юности избрав монашеский путь. Приняв постриг в Спасо-Каменном монастыре, 9 лет подвизался в аскезе." },
  { key: "06-14", name: "св. прав. Иоанна Кронштадтского", kind: "saint", desc: "Св. прав. Иоанн Кронштадтский (1829-1908) — великий пастырь и чудотворец. Сын бедного сельского дьячка из Архангельской губернии, с детства проявлял особую религиозность.", lifeId: "ioann-kronstadt" },
  { key: "06-14", name: "Прп. Агапита Печерского, врача безмездного, в Ближних пещерах", kind: "saint", desc: "Прп. Агапит Печерский (XI в.) ‒ киевский монах, ученик прп. Антония Печерского, прославился как безмездный врач. Лечил больных молитвой и травами. Исцелил князя Владимира Мономаха, но скрылся от благодарности." },
  { key: "06-14", name: "прп. Иустина Поповича, Челийского (1979)", kind: "saint", desc: "Прп. Иустин (Попович) Челийский (1894-1979) – сербский богослов и подвижник. Родился в священнической семье, обучался в Белграде, Петербурге и Оксфорде." },
  { key: "06-14", name: "Всех преподобных и богоносных отцов, во Святой Горе Афонской просиявших", kind: "saint", desc: "Когда, по преданию, в Иерусалиме святые апостолы вместе с Божией Матерью определили по жребию, кому какая страна достанется для евангельской проповеди, Пречистой Деве Марии досталась Иверская земля (Грузия)." },
  { key: "06-14", name: "Сщмч. Василия Преображенского, пресвитера", kind: "saint", desc: "Сщмч. Василий Преображенский (1876-1940) родился в семье псаломщика в Ярославской губернии. После службы в армии принял священный сан. В 1937 году, после закрытия храма, тайно совершал требы на дому." },
  { key: "06-14", name: "мц. Веры Самсоновой", kind: "saint", desc: "Мученица Вера Самсонова (1880-1940) родилась в Тамбовской губернии, работала учительницей до запрета религиозного образования. Став старостой Пятницкой церкви в Касимове, ревностно защищала веру." },
  { key: "06-15", name: "Свт. Никифора исп., патриарха Константинопольского", kind: "saint", desc: "Свт. Никифор Исповедник (ок. 758-828) ‒ патриарх Константинопольский (806-815), выдающийся борец с иконоборчеством. Родился в благочестивой семье, получил блестящее образование." },
  { key: "06-15", name: "вмч. Иоанна Нового, Сочавского", kind: "saint", desc: "Св. вмч. Иоанн Новый, Сочавский (XIV в.), благочестивый купец из Трапезунда, пострадал за веру в Белграде Босфорском. Обманутый капитаном-отступником, он отказался принять огнепоклонничество и после жестоких пыток (биение палками, влачение конём) был обезглавлен." },
  { key: "06-15", name: "Обретение мощей мц. прав. Иулиании, кн. Вяземской, Новоторжской", kind: "saint", desc: "Блгв. княгиня Иулиания Вяземская (†1406) ‒ супруга князя Симеона Мстиславича, пострадавшая за верность браку. После изгнания из Смоленска жила в Торжке, где князь Юрий Святославич, воспылав страстью, убил её мужа и пытался овладеть ею." },
  { key: "06-15", name: "сщмч. Пофина, епископа Лионского, и с ним пострадавших", kind: "saint", desc: "Св. Пофин Лионский (II в.) — епископ Лиона, пострадавший во время гонений Марка Аврелия. В 177 году 90-летний старец был арестован вместе с другими христианами." },
  { key: "06-15", name: "Киево-Братская", year: "1654", kind: "saint", desc: "Чудотворная Киево-Братская икона Божией Матери была явлена в 1654 году и первоначально была местной в Борисоглебской церкви города Вышгорода (Киевского)." },
  { key: "06-16", name: "Перенесение мощей блгв. царевича Димитрия из Углича в Москву", kind: "saint", desc: "Младший сын Ивана Грозного. В 8 лет убит в Угличе по приказу Бориса Годунова. Прославлен как невинный страстотерпец. Мощи обретены нетленными (1606), перенесены в Архангельский собор Московского Кремля." },
  { key: "06-16", name: "Прмч. Киприана (Нелидова), иеромонаха", kind: "saint", desc: "Прмч. Киприан (Нелидов, 1901–1934) – сын дворянина-врача из Казани. После службы в армии принял постриг и был рукоположен в иеромонахи (1925). Служил в Казахстане, затем в Москве, где жил в квартире епископа Варнавы (Беляева)." },
  { key: "06-16", name: "сщмч. Михаила Горетовского (Маркова), пресвитера", kind: "saint", desc: "Сщмч. Михаил Марков (1881-1938) — священник из Подмосковья, выпускник Вифанской семинарии. Неоднократно преследовался властями: в 1929 году чудом избежал 8-летней ссылки за сбор средств на храм, в 1933 году осуждён на 3 года лагерей за противодействие закрытию церкви." },
  { key: "06-16", name: "Одигитрия Югская", year: "1615", kind: "saint", desc: "Чудотворная икона Божией Матери, именуемая Югская, явилась в начале ХVII века старцу схимонаху Псково-Печерского монастыря преподобному Дорофею. Богородица, во время нашествия шведов, повелела ему взять Ее образ в указанном Ею месте, отнести образ в пределы Ярославской епархии и там основать обитель." },
  { key: "06-17", name: "Свт. Митрофана, патриарха Константинопольского", kind: "saint", desc: "Свт. Митрофан (III-IV вв.) ‒ 1-й патриарх Константинопольский, происходил из знатного римского рода. Его отец Дометий, племянник императора Проба, принял христианство и стал епископом Византия." },
  { key: "06-17", name: "Прп. Мефодия, игумена Пешношского", kind: "saint", desc: "Прп. Мефодий Пешношский (XIV в.) ‒ ученик прп. Сергия Радонежского, основатель Николо-Пешношского монастыря под Дмитровом. Поселившись в глухом лесу за рекой Яхромой, он по совету своего наставника перенёс обитель на более удобное место, ли" },
  { key: "06-17", name: "сщмч. Конкордия Римлянина, пресвитера", kind: "saint", desc: "Св. мч. Конкордий (II в.) — сын пресвитера Гордиана. За отказ принести жертву языческим богам был подвергнут пыткам правителем Торкватом. После освобождения епископом Анфимом принял сан пресвитера." },
  { key: "06-17", name: "сщмч. Астия, епископа Диррахийского", kind: "saint", desc: "Сщмч. Астий, епископ Диррахийский (II в.), пострадал при императоре Траяне. После видения о предстоящих муках отпустил клир, сам же был схвачен, избит, обмазан медом, чтобы увеличить страдания от укусов шершней и мух, и распят." },
  { key: "06-17", name: "прп. Зосимы, епископа Вавилона Египетского", kind: "saint", desc: "Прп. Зосима Вавилонский (VI в.) – подвижник, начавший иноческий путь на Синае, затем уединился в Ливии. По пророчеству старца стал епископом Вавилона, где долгие годы мудро управлял паствой." },
  { key: "06-17", name: "сщмч. Георгия Богича, пресвитера", kind: "saint", desc: "Сщмч. Георгий Богич (1911-1941) ‒ сербский священник, выпускник Сараевской семинарии. В ночь на 17 июня 1941 года был зверски убит усташами (хорватскими националистами) близ Нашице: после жестоких пыток (отрезание носа, ушей, языка, выкалывание глаз) был расстрелян.", lifeId: "georgiy" },
  { key: "06-17", name: "сщмч. Иоанникия, митрополита Черногорско-Приморского (1945)", kind: "saint", desc: "Сщмч. Иоанникий (Липовац) (1890-1945) ‒ митрополит Черногорско-Приморский. Родился в Черногории. Во время Второй мировой войны открыто выступал против коммунистических гонений на Церковь." },
  { key: "06-17", name: "Сщмч. Петра Беляева, пресвитера", kind: "saint", desc: "Сщмч. Петр Беляев (1874-1918) ‒ выпускник Владимирской семинарии, служил в Успенском храме Каслинского завода (Урал). Активно занимался миссионерством среди башкир, преподавал Закон Божий." },
  { key: "06-17", name: "сщмч. Петра (Зверева), архиепископа Воронежского", kind: "saint", desc: "Сщмч. Петр (Зверев) (1878-1929), архиепископ Воронежский. После закрытия властями Воронежского монастыря в 1926 году был осуждён по ст. 58 УК РСФСР (контрреволюционная пропаганда), приговорён к 10 годам лагерей и сослан в Соловецкий лагерь." },
  { key: "06-18", name: "Сщмч. Дорофея, епископа Тирского", kind: "saint", desc: "Сщмч. Дорофей, епископ Тирский (III–IV вв.), скрывался от гонений Диоклетиана, но при св. Константине Великом вернулся и 50 лет управлял паствой, обращая язычников." },
  { key: "06-18", name: "Перенесение мощей блгв. вел. кн. Игоря (во Святом Крещении Георгия) Черниговского и Киевского", kind: "saint", desc: "Св. блгв. кн. Игорь Черниговский (†1147) стал жертвой княжеских междоусобиц. После краткого киевского княжения был свергнут, пострижен в схиму, но через год убит восставшими киевлянами прямо в храме во время молитвы перед иконой Богородицы (впоследствии названной Игоревской)." },
  { key: "06-18", name: "блж. Константина, митрополита Киевского и всея Руси", kind: "saint", desc: "Блаженный Константин, митрополит Киевский (XII в.) восстановил канонический порядок в Русской Церкви после смуты 1147 года. Прибыв из Константинополя в 1156 году, он отменил решения незаконного собора и укрепил единство с Вселенской Церковью." },
  { key: "06-18", name: "блгв. кн. Феодора Ярославича (брата св. Александра Невского), Новгородского", kind: "saint", desc: "Святый князь Феодор был старший сын князя Ярослава Всеволодовича, родившийся в 1219 г. По летописям он и младший брат его Александр в 1228 г. оставлены были отцом в Новгороде, как представители его власти." },
  { key: "06-18", name: "Обретение мощей прпп. Вассиана", kind: "saint", desc: "Прпп. Вассиан и Иона Пертоминские ‒ соловецкие иноки XVI века, ученики св. Филиппа (будущего митрополита Московского). Погибли в 1561 году во время шторма, выполняя послушание по доставке строительных материалов для монастыря." },
  { key: "06-18", name: "Ионы Пертоминских, Соловецких чудотворцев", kind: "saint", desc: "Прпп. Вассиан и Иона Пертоминские ‒ соловецкие иноки XVI века, ученики св. Филиппа (будущего митрополита Московского). Погибли в 1561 году во время шторма, выполняя послушание по доставке строительных материалов для монастыря." },
  { key: "06-18", name: "прп. Феодора Иорданского, чудотворца", kind: "saint", desc: "Прп. Феодор Иорданский (VI в.) — пустынник, прославившийся даром чудотворения. Так, однажды во время морского путешествия по его молитве солёная вода превратилась в пресную, утолив жажду спутников." },
  { key: "06-18", name: "прп. Анувия, пустынника Египетского", kind: "saint", desc: "Прп. Анувий Египетский (IV в.) ‒ исповедник, переживший гонения и удалившийся в пустыню. Основал скит с шестью иноками, включая брата ‒ прп. Пимена Великого." },
  { key: "06-18", name: "прп. Дорофея Палестинского, из обители аввы Серида", kind: "saint", desc: "Прп. Дорофей Палестинский (VI в.) ‒ великий подвижник, ученик прпп. Иоанна Пророка и Варсануфия Великого. В молодости получил блестящее образование, но оставил мир ради монашества." },
  { key: "06-18", name: "Сщмч. Михаила Чистопольского (Вотякова), пресвитера", kind: "saint", desc: "Сщмч. Михаил Вотяков (1881-1931) ‒ священник из Казанской губернии. Служил в сельских храмах, несмотря на гонения. В 1931 году обвинён в \"антисоветской агитации\" за проповеди, в которых упоминал трудности жизни при советской власти и просил помощи для уплаты церковных налогов." },
  { key: "06-18", name: "сщмч. Николая Рюрикова, пресвитера", kind: "saint", desc: "Сщмч. Николай Рюриков (1884-1943) родился в Нижегородской губернии. Окончив духовную семинарию, преподавал в церковноприходских школах, а в 1910 г. был рукоположен во священника." },
  { key: "06-18", name: "Игоревская", year: "1147", kind: "saint", desc: "История иконы связана с памятью о святом великом князе Игоре из рода Ольговичей, в крещении Георгии, в иночестве Гаврииле, убитом в Киеве в 1147 году (память 18 июня и 2 октября по новому стилю)." },
  { key: "06-19", name: "Прп. Виссариона Египетского, чудотворца", kind: "saint", desc: "Прп. Виссарион Египетский (IV-V вв.) – великий подвижник, ученик прп. Исидора Пелусиота. Приняв крещение, путешествовал по святым местам, изучая монашескую жизнь." },
  { key: "06-19", name: "прп. Илариона Нового, игумена", kind: "saint", desc: "Прп. Иларион Новый (VIII-IX вв.) — византийский подвижник, ученик прп. Григория Декаполита. Став игуменом Далматской обители, мужественно противостоял иконоборцам." },
  { key: "06-19", name: "Свт. Ионы, епископа Великопермского", kind: "saint", desc: "Свт. Иона, епископ Великопермский (XV в.) — преемник убитого вогуличами свт. Питирима, завершивший христианизацию Великой Перми. Обратил языческие племена по рекам Вишере, Каме и Чусовой, уничтожил идолов и построил храмы с училищами." },
  { key: "06-19", name: "прп. Паисия Угличского, игумена", kind: "saint", desc: "Прп. Паисий Угличский (XV–XVI вв.) ‒ племянник и ученик прп. Макария Калязинского. С 11 лет воспитывался в монастыре, где подвизался в посте, молитве и переписывании книг." },
  { key: "06-19", name: "прп. Ионы Климецкого (Клименецкого)", kind: "saint", desc: "Прп. Иона Климецкий (XV–XVI вв.) ‒ основатель Троицкого монастыря на Онежском озере. Будучи купцом, во время бури дал обет посвятить жизнь Богу. После чудесного спасения обрёл икону Пресвятой Троицы и основал обитель с двумя храмами – во имя Пресвятой Троицы и в честь свт." },
  { key: "06-19", name: "Прп. Рафаила (Шейченко), исп., иеромонаха", kind: "saint", desc: "Прписп. Рафаил (в миру Родион Шейченко, 1891-1957) родился в Курской губернии. Стал послушником Оптиной пустыни. После закрытия монастыря в 1923 г. жил в Козельске, работал сапожником." },
  { key: "06-19", name: "Пименовская", kind: "saint", desc: "Первое упоминание об иконе относится ко второй половине XVI века. Краткая запись в Книге Степенной царского родословия о двух мироточивых иконах в Москве – Богоматери и Николая Чудотворца была дополнена следующим сообщением: «Сию чудесную и" },
  { key: "06-20", name: "Мч. Феодота Анкирского", kind: "saint", desc: "Св. мч. Феодот и семь дев-мучениц пострадали за веру в Анкире в начале IV века. Феодот, владелец гостиницы, беседами приводил язычников к христианской вере, помогал христианам во время гонений, хоронил мучеников." },
  { key: "06-20", name: "прав. Павла Таганрогского", kind: "saint", desc: "Прав. Павел Таганрогский (1792–1879), дворянский сын, раздал имущество и посвятил жизнь Богу. Поселившись в Таганроге, он жил в бедности, работал в порту, молился и наставлял людей." },
  { key: "06-20", name: "Собор святых Ивановской митрополии", kind: "feast", desc: "Благословением Святейшего Патриарха Кирилла от 7 мая 2015 года утвержден Собор святых Ивановской митрополии. Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года (журнал № 31)." },
  { key: "06-20", name: "Андроника (Никольского), архиепископа Пермского", kind: "saint", desc: "Сщмч. Андроник (в миру Владимир Никольский), архиепископ Пермский, родился в 1870 году в семье диакона. Приняв монашество, он служил миссионером в Японии, затем управлял различными епархиями." },
  { key: "06-20", name: "Александра Осетрова", kind: "saint", desc: "Сщмч. Александр Осетров, священник, служил в Никольском храме села Телёс в Пермской губернии. В 1918 году, в возрасте 23 лет, он был убит большевиками: изрублен шашками и расстрелян." },
  { key: "06-20", name: "Валентина Белова", kind: "saint", desc: "Сщмч. Валентин Белов родился в 1891 году в семье диакона. Окончив духовное училище, в 1909 году стал псаломщиком в Покровской церкви села Поташка в Пермской губернии, затем законоучителем." },
  { key: "06-20", name: "Вениамина Луканина", kind: "saint", desc: "Сщмч. Вениамин Луканин родился в 1875 г. в семье псаломщика. С 1891 г. служил псаломщиком, преподавал в школах. В 1902 г. рукоположен во диакона, в 1907-м – во священника." },
  { key: "06-20", name: "Виктора Никифорова", kind: "saint", desc: "Сщмч. Виктор Никифоров родился в семье диакона. Окончил Пермскую духовную семинарию в 1917 г. 20 февраля 1918 г. рукоположен в священники и назначен в Петропавловский храм села Комаровского." },
  { key: "06-20", name: "Александра Махетова", kind: "saint", desc: "Сщмч. Александр Махетов родился в 1868 г. в крестьянской семье в Уфимской губернии. Окончив учительскую семинарию, преподавал в земских училищах. В 1894 г." },
  { key: "06-20", name: "Владимира Белозерова", kind: "saint", desc: "Сщмч. Владимир Белозеров родился в 1869 г. Окончив Пермскую духовную семинарию в 1889 г, был рукоположен во священника и служил в Богоявленской церкви села Савинское, затем в Троицком храме села Асов, Вознесенской церкви и Благовещенском соборе г." },
  { key: "06-20", name: "Игнатия Якимова", kind: "saint", desc: "Сщмч. Игнатий Якимов родился в 1872 г. в крестьянской семье в Вятской губернии. Окончив духовное училище, служил псаломщиком, в 1899 году рукоположен во диакона, в 1903-м ‒ во священника." },
  { key: "06-20", name: "Михаила Денисова", kind: "saint", desc: "Сщмч. Михаил Денисов родился в 1869 г. в Пермской губернии. Окончив 3 класса Пермской духовной семинарии, служил псаломщиком, в 1897 году рукоположен во диакона, в 1911-м ‒ во священника." },
  { key: "06-20", name: "Николая Онянова", kind: "saint", desc: "Сщмч. Николай Онянов родился в 1862 г. в Пермской губернии. Окончив училище, в 1879 г. определен церковником, затем псаломщиком. В 1888 г. рукоположен во диакона, в 1904-м ‒ во священника." },
  { key: "06-20", name: "Павла Кунгурского", kind: "saint", desc: "Отец Павел Соколов, настоятель Тихвинского храма в г. Кунгуре, родился в 1874 г. в семье священника. Окончив Калужскую духовную семинарию в 1896 г., он преподавал Закон Божий, затем переехал в Пермскую губернию." },
  { key: "06-21", name: "Вмч. Феодора Стратилата", kind: "saint", desc: "Вмч. Феодор Стратилат, военачальник из Евхаит, прославился доблестью и верой. Убил чудовищного змея с Божией помощью, обратил в христианство жителей Гераклеи." },
  { key: "06-21", name: "Свт. Феодора, епископа Ростовского и Суздальского", kind: "saint", desc: "Свт. Феодор, епископ Ростовский и Суздальский, прибыл на Русь из Константинополя в свите свт. Михаила, крестившего св. князя Владимира. В 990 г. стал первым епископом Ростова, где построил собор в честь Богородицы." },
  { key: "06-21", name: "Обретение мощей блгвв. кнн. Василия", kind: "saint", desc: "Св. блгв. князья Василий и Константин Ярославские, сыновья князя Всеволода Константиновича, погибшего в битве с монголами на реке Сить (†1238). Князь Василий (†1249) мудро правил Ярославским княжеством, восстанавливал храмы, ездил в Орду для защиты земель." },
  { key: "06-21", name: "Константина Ярославских", kind: "saint", desc: "Св. блгв. князья Василий и Константин Ярославские, сыновья князя Всеволода Константиновича, погибшего в битве с монголами на реке Сить (†1238). Князь Василий (†1249) мудро правил Ярославским княжеством, восстанавливал храмы, ездил в Орду для защиты земель." },
  { key: "06-21", name: "прп. Ефрема, патриарха Антиохийского", kind: "saint", desc: "Свт. Ефрем, патриарх Антиохийский, бывший военачальник при императорах Анастасии и Иустине. В 527 г. избран патриархом, проявив себя мудрым архипастырем, защитником православия от ересей." },
  { key: "06-21", name: "прп. Зосимы Финикийского", kind: "saint", desc: "Прп. Зосима Финикийский, сирийский подвижник, подвизался в посте, молитвах и добродетелях. Прославился даром прозорливости (предвидел антиохийское землетрясение 526 г.) и чудотворения (предсказал исцеление жены патриция Аркесилая)." },
  { key: "06-21", name: "Празднество в Вологде всем преподобным отцам Вологодским", kind: "saint", desc: "Земля Вологодская дорога сердцу каждого русского православного по множеству бывших в ней обителей иноческих и подвизавшихся в них великих угодников Божиих." },
  { key: "06-21", name: "Собор Новгородских святых", kind: "feast", desc: "Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года (журнал № 31). Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажми" },
  { key: "06-21", name: "Собор Белорусских святых", kind: "feast", desc: "Установлен 3 апреля 1984 года по инициативе митрополита Минского и Белорусского Филарета (Вахромеева). За двадцать с лишним лет Собор Белорусских святых возрос от 14 до 79 угодников Божиих." },
  { key: "06-21", name: "Собор Псковских святых", kind: "feast", desc: "В Неделю 3-ю по Пятидесятнице Святая Церковь празднует Собор Псковских святых (переходящее празднование). Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года (журнал № 31)." },
  { key: "06-21", name: "Собор святых Санкт-Петербургской митрополии", kind: "feast", desc: "Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года (журнал № 31). Текст утвержден Священным Синодом Русской Православной Церкви 22 октября 2015 года (журнал № 80)" },
  { key: "06-21", name: "Собор святых Удмуртской земли", kind: "feast", desc: "Празднование Собора святых Удмуртской земли внесено в месяцеслов по благословению Патриарха Московского и всея Руси Кирилла 14 июня 2018 года. Днем празднования Собора установлена 3-я Неделя по Пятидесятнице." },
  { key: "06-21", name: "Собор Волгоградских святых", kind: "feast", desc: "День празднования Собора Волгоградских святых установлен решением Священного Синода Русской Православной Церкви от 16 мая 2023 года (журнал № 31). Празднование совершается в Неделю 3-ю по Пятидесятнице." },
  { key: "06-21", name: "Собор святых Чувашской митрополии", kind: "feast", desc: "Поименный список Собора святых Чувашской митрополии утвержден решением Священного Синода 20 марта 2025 года (журнал № 13). Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите те" },
  { key: "06-22", name: "Принесение в Свято-Троицкую Сергиеву Лавру образа Святой и Живоначальной Троицы, написанного прп. Андреем Рублевым", year: "2024", kind: "feast", desc: "22 июня 2024 года состоялось историческое событие – в Свято-Троицкую Сергиеву Лавру в подмосковном Сергиевом Посаде была возвращена икона «Троица», написанная прп." },
  { key: "06-22", name: "Свт. Кирилла, архиепископа Александрийского", kind: "saint", desc: "Свт. Кирилл Александрийский (†444) – выдающийся богослов и защитник Православия. Возглавив Александрийскую Церковь в 412 г., он боролся с ересями новациан и иудеев, а позже – с несторианством, отрицавшим Божественное достоинство Христа и наименование Девы Марии Богородицей." },
  { key: "06-22", name: "прп. Кирилла, игумена Белоезерского", kind: "saint", desc: "Прп. Кирилл Белоезерский (†1427), в миру Косма, родился в Москве. Приняв постриг в Симоновом монастыре, стал игуменом, но избегая славы, ушел в затвор." },
  { key: "06-22", name: "прав. Алексия Московского (Мечёва)", kind: "saint", desc: "Св. прав. Алексий Мечёв (1859-1923) родился в Москве в семье регента. По благословению матери стал священником. 40 лет прослужил в малоприходном храме свт.", lifeId: "aleksey-mechov" },
  { key: "06-22", name: "Прп. Александра, игумена Куштского", kind: "saint", desc: "Прп. Александр Куштский (ок. 1371–1439), вологодский подвижник, принял постриг в Спасо-Каменном монастыре. Стремясь к уединению, основал пустынь на реке Куште, где позже возник Успенский монастырь." },
  { key: "06-22", name: "Обретение мощей прп. Рафаила (Шейченко), исп., иеромонаха", kind: "saint", desc: "Прписп. Рафаил (в миру Родион Шейченко, 1891-1957) родился в Курской губернии. Стал послушником Оптиной пустыни. После закрытия монастыря в 1923 г. жил в Козельске, работал сапожником." },
  { key: "06-23", name: "Сщмч. Тимофея, епископа Прусского", kind: "saint", desc: "Сщмч. Тимофей, епископ Прусский, прославился праведной жизнью и даром чудотворений, обратив многих язычников в христианство. Во время гонений императора-отступника Юлиана (IV век) был заключён в темницу, но не прекратил проповедь." },
  { key: "06-23", name: "Обретение мощей свт. Василия, епископа Рязанского", kind: "saint", desc: "По преданию, свт. Василий Рязанский начал свой духовный путь в Муроме, где принял монашество и был поставлен епископом. Когда по козням дьявола муромцы заподозрили его в грехе и изгнали, святитель чудесным образом переплыл на своей мантии по Оке до Рязани (200 км), держа в руках икону Богоматери." },
  { key: "06-23", name: "Собор Рязанских святых", kind: "feast", desc: "Установлен 12 января 1987 года по инициативе архиепископа Рязанского и Касимовского Симона (Новикова) и по благословению патриарха Московского и всея Руси Пимена." },
  { key: "06-23", name: "свт. Иоанна (Максимовича), митрополита Тобольского", kind: "saint", desc: "Свт. Иоанн Тобольский (1651-1715), в миру Иоанн Максимович, родился в Нежине. Окончив Киево-Могилянскую коллегию, принял монашество в Киево-Печерской лавре." },
  { key: "06-23", name: "Собор святых Тобольской митрополии", kind: "feast", desc: "С присоединением Сибири к России началась история Тобольско-Сибирской епархии, утвержденной в 1620 году как архиепископии, а затем преобразованной в митрополию, из которой впоследствии были образованы другие Сибирские епархии." },
  { key: "06-23", name: "сщмч. Митрофана Китайского, пресвитера, и иже с ним мучеников многих", kind: "saint", desc: "В 1900 г. в Китае произошло восстание ихэтуаней («боксерское»), направленное против иностранцев и христиан. Православная миссия в Пекине подверглась разгрому: 11 июня 1900 г." },
  { key: "06-23", name: "Прп. Силуана, схимника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Силуан, Киево-Печерский схимник (XIII-XIV вв.), прославился строгой аскезой, непрестанной молитвой и духовными дарами – прозорливостью, чудотворениями и особой благодатной радостью." },
  { key: "06-23", name: "прп. Феофана Антиохийского", kind: "saint", desc: "Прп. Феофан Антиохийский, обратившийся ко Христу после смерти жены, вёл аскетическую жизнь, проповедуя целомудрие. Узнав о блуднице Пансемине, он мудро подошёл к её спасению: под видом жениха подарил золото, убедил креститься и изменить жизнь." },
  { key: "06-23", name: "свт. Вассиана, епископа Лавдийского", kind: "saint", desc: "Свт. Вассиан, епископ Лавдийский (IV-V вв.), происходил из знатной сицилийской семьи. В юности, тайно приняв крещение в Риме, он оставил мирскую карьеру и раздал имущество." },
  { key: "06-23", name: "Прп. Фамари (Марджановой), исп., игумении (1936)", kind: "saint", desc: "Схиигумения Фамарь (в миру княжна Тамара Марджанишвили) родилась в 1868 г. в Грузии. Приняв постриг в Бодбийском монастыре, в 1905 г. стала настоятельницей московского Покровского монастыря." },
  { key: "06-23", name: "Сщмч. Тимофея Ульянова, пресвитера", kind: "saint", desc: "Сщмч. Тимофей Ульянов родился в 1900 г. в крестьянской семье. С 1917 г. служил псаломщиком, в 1932 году рукоположен во священника. Служил в Вознесенском храме села Сатино-Русское в Московской области." },
  { key: "06-24", name: "Апп. Варфоломея", kind: "saint", desc: "Св. апостол Варфоломей, один из 12 учеников Христа, проповедовал в Сирии, Малой Азии и Индии, где перевел Евангелие по Матфею. В Армении исцелил царскую дочь, обратил многих ко Христу, за что был казнен язычниками ‒ его распяли, с живого содрали кожу и обезглавили (71 г.)." },
  { key: "06-24", name: "и Варнавы", kind: "saint", desc: "Апостол Варнава, один из 70 учеников Христа. Совместно с апостолом Павлом проповедовал в Малой Азии и на Кипре, основал епископскую кафедру в Медиолане (Милане)." },
  { key: "06-24", name: "Прп. Варнавы Ветлужского", kind: "saint", desc: "Прп. Варнава Ветлужский (XIV-XV вв.) – подвижник, основатель Варнавинской пустыни. Уроженец Великого Устюга, священник, он 28 лет провёл в отшельничестве на берегу реки Ветлуги, где, по преданию, мирно сосуществовал с дикими зверями." },
  { key: "06-24", name: "Перенесение мощей прп. Ефрема Новоторжского, архимандрита", kind: "saint", desc: "Прп. Ефрем Новоторжский, венгр по происхождению, прибыл на Русь вместе с братьями св. Моисеем Угрином и св. Георгием, поступив на службу к св. князю Ростовскому Борису." },
  { key: "06-24", name: "Достойно есть (Милующая)", kind: "saint", desc: "Икона Божией Матери «Достойно есть» (греч. Ἄ&xi;&iota;&omicron;&nu; Ἐ&sigma;&tau;ί, Аксион эстин ) находится на горнем месте алтаря соборного храма Карейской обители на Афоне ." },
  { key: "06-25", name: "Прп. Онуфрия Великого", kind: "saint", desc: "Один из величайших египетских пустынников IV века. Оставив монастырь в юности, он 60 лет подвизался в полном одиночестве в Фиваидской пустыне. По Божьей милости пальма и источник обеспечивали его пропитанием, а Ангел регулярно причащал." },
  { key: "06-25", name: "прп. Петра Афонского", kind: "saint", desc: "Прп. Петр Афонский (VII-VIII вв.) – греческий военачальник, попавший в плен к сирийцам. В заточении дал обет принять монашество. Был чудесно освобожден по молитвам к свт." },
  { key: "06-25", name: "Перенесение мощей (1650) и второе прославление (1909) блгв. вел. кн. Анны Кашинской", kind: "saint", desc: "Св. блгв. княгиня Анна Кашинская (1280-1368), супруга тверского князя Михаила, пережила гибель мужа и сыновей в Орде, разорение Твери. Приняв монашество, стала образцом терпения и веры." },
  { key: "06-25", name: "прп. Арсения Коневского", kind: "saint", desc: "Новгородский ремесленник, принявший монашество. 3 года подвизался на Афоне, где получил в благословение Коневскую икону Божией Матери. В 1393 г. основал на Ладожском озере Коневский Рождество-Богородичный монастырь." },
  { key: "06-25", name: "прп. Онуфрия Мальского, Псковского", kind: "saint", desc: "Прп. Онуфрий Мальский (XV в.) основал обитель в честь Рождества Богородицы под Изборском. Скончался 12 июня 1492 г., погребён в монастырском храме. Преподобный Онуфрий Мальский, Псковский (Изборский) основал обитель в честь Рождества Богородицы в Малах, в четырех верстах от Изборска и в 56 верстах от Пскова." },
  { key: "06-25", name: "прп. Стефана Озерского, Комельского", kind: "saint", desc: "Прп. Стефан Комельский (XV-XVI вв.) – выходец из знатного рода, оставивший придворную жизнь ради монашества. Подвизался в Глушицкой обители, затем в поисках уединения поселился у Комельского озера, где после явления Пресвятой Богородицы и св." },
  { key: "06-26", name: "Мц. Акилины Старшей", kind: "saint", desc: "Св. мц. Акилина (ок. 281-293 гг.), 12-летняя христианка из финикийского Библа, пострадала при императоре Диоклетиане. За обращение сверстниц в христианство была подвергнута жестоким пыткам: бичеванию и прожиганию головы раскалёнными прутьями." },
  { key: "06-26", name: "свт. Трифиллия, епископа Левкусии Кипрской", kind: "saint", desc: "Свт. Трифиллий, епископ Левкуссийский (IV в.), ученик свт. Спиридона Тримифунтского, прославился учёностью и красноречием. Будучи епископом на Кипре, преодолевал мирские искушения под руководством своего наставника." },
  { key: "06-26", name: "прп. Александры Дивеевской (Мельгуновой)", kind: "saint", desc: "Прп. Александра Дивеевская (в миру Агафия Мельгунова, ок. 1720-1789) – основательница Дивеевской обители. Овдовев, раздала имение и по благословению Богородицы поселилась в Дивееве, где построила Казанский храм." },
  { key: "06-26", name: "Андроника, игумена (ок. 1395),", kind: "saint", desc: "Прп. Андроник Московский (XIV-XV вв.) – ученик прп. Сергия Радонежского, основатель Спасо-Андроникова монастыря в Москве (1361 г.). Он создал строгую общежительную обитель, воспитавшую таких подвижников, как прп." },
  { key: "06-26", name: "Саввы (XV), Московских", kind: "saint", desc: "Прп. Савва Московский (XIV-XV вв.) – ученик прп. Андроника Московского, второй игумен Спасо-Андроникова монастыря. Прославился добродетелями и мудрым управлением обителью, воспитал многих игуменов и епископов." },
  { key: "06-26", name: "мц. Антонины Никейской", kind: "saint", desc: "Св. мц. Антонина Никейская пострадала при императоре Максимиане (начало IV в.). После жестоких пыток, включая раскалённый одр, была утоплена в озере, оставшись верной Христу." },
  { key: "06-26", name: "Анны (Евфимиана) (826) и сына ее", kind: "saint", desc: "Прп. Анна (VIII-IX вв.) – византийская подвижница, принявшая мужской монашеский образ под именем Евфимиан. После смерти мужа, вместе со своим сыном св." },
  { key: "06-26", name: "Иоанна Вифинского", kind: "saint", desc: "Прп. Иоанн Вифинский (VIII-IX вв.) ‒ сын св. Анны, известной как монах Евфимиан. После смерти супруга Анна оставила мир, взяв с собой юного Иоанна, и вместе они отправились в монастырь на горе Олимп в Вифинии (северо-запад Малой Азии)." },
  { key: "06-26", name: "Собор мучеников Житомисличских (1941)", year: "Серб.", kind: "feast", desc: "Святые мученики Житомисличские — игумен старинного сербского монастыря Житомислич (Захумско-Герцеговинская епархия) Константин (Вучуревич, 1908-1941), насельники обители иеромонахи Досифей (Вукичевич, 1915-1941) и Макарий (Пеяк, 1915-1941)," },
  { key: "06-26", name: "Сщмч. Алексия Архангельского, пресвитера", kind: "saint", desc: "Сщмч. Алексий Архангельский (1864-1918) – священник Пермской епархии. Окончив 3 курса семинарии, служил псаломщиком, затем был рукоположен в священники." },
  { key: "06-26", name: "мц. Пелагии Жидко", kind: "saint", desc: "Мц. Пелагия Жидко (1897-1944) – крестьянка из Воронежской губернии. После закрытия храмов состояла в подпольных христианских общинах. В 1937 году арестована за \"антиколхозную пропаганду\" и осуждена на 10 лет лагерей." },
  { key: "06-27", name: "Прор. Елисея", kind: "saint", desc: "Св. пророк Елисей жил в IX веке до Р. X., был призван к пророческому служению пророком Илией и служил более 65 лет при шести израильских царях. Он творил множество чудес: разделил Иордан, исцелил воду Иерихонского источника, чудесно напоил " },
  { key: "06-27", name: "свт. Мефодия, патриарха Константинопольского", kind: "saint", desc: "Свт. Мефодий, патриарх Константинопольский, родился в Сицилии в богатой семье, в молодости ушел в монастырь на Хиосе. При иконоборце Льве Армянине служил апокрисиарием у патриарха Никифора, позже был отправлен в Рим, а после свержения Никифора вернулся и противостоял иконоборчеству." },
  { key: "06-27", name: "Обретение мощей сщмч. Владимира (Богоявленского), митрополита Киевского", kind: "saint", desc: "Сщмч. Владимир (Богоявленский, 1848–1918) родился в семье священника, окончил Киевскую Духовную Академию и стал преподавателем, а затем священником. После смерти жены и ребенка принял монашество." },
  { key: "06-27", name: "Блгв. кн. Мстислава, во Святом Крещении Георгия, Храброго, Новгородского", kind: "saint", desc: "Блгв. кн. Новгородский Мстислав Храбрый, внук Мстислава Киевского, прославился доблестью и милосердием. В 1168 году он отстоял Киев для брата Рюрика. Позже княжил в Смоленске и Новгороде." },
  { key: "06-27", name: "прп. Мефодия, игумена Пешношского", kind: "saint", desc: "Прп. Мефодий Пешношский (XIV в.) ‒ ученик прп. Сергия Радонежского, основатель Николо-Пешношского монастыря под Дмитровом. Поселившись в глухом лесу за рекой Яхромой, он по совету своего наставника перенёс обитель на более удобное место, ли" },
  { key: "06-27", name: "прп. Елисея Сумского", kind: "saint", desc: "Прп. Елисей Сумский (XV–XVI) прославился чудесным предсмертным подвигом. Когда во время рыбной ловли ему предрекли скорую кончину, он скорбел о невозможности принять схиму." },
  { key: "06-27", name: "Собор Дивеевских святых", kind: "feast", desc: "Текст утвержден Священным Синодом Русской Православной Церкви 28 декабря 2017 года (журнал № 131) Месяца августа в 5-й день и месяца мая в 23-й день Новомучениц Евдокии, Дарии, Дарии и Марии Пузинских" },
  { key: "06-27", name: "Сщмчч. Иосифа Сикова,", kind: "saint", desc: "Сщмч. Иосиф Сиков родился в 1873 году. Окончив миссионерскую школу, он был рукоположен в диакона, а затем ‒ в священника Знаменской церкви Верхнетагильского завода на Урале." },
  { key: "06-27", name: "Димитрия Семенова, пресвитеров", kind: "saint", desc: "Сщмч. Димитрий Семенов родился в 1873 г. в семье священника в Ставропольской губернии. Окончив 3 класса духовной семинарии, работал учителем, затем был рукоположен в диакона." },
  { key: "06-27", name: "Александра Парусникова", kind: "saint", desc: "Сщмч. Александр Парусников (1879-1938) родился в семье священника Московской губернии. Окончив духовную семинарию, принял сан в 1908 г. и служил в Троицком храме села Раменское." },
  { key: "06-27", name: "Павла Иванова", kind: "saint", desc: "Сщмч. Павел Иванов (1875-1938) родился в семье священника Смоленской губернии. Окончив духовную семинарию, преподавал в школе. После смерти отца был рукоположен в сан и назначен в Успенский храм родного села." },
  { key: "06-27", name: "Николая Запольского, диакона", kind: "saint", desc: "Сщмч. Николай Запольский (1889-1938) родился в семье священника Московской губернии. Окончив духовное училище, служил псаломщиком, затем диаконом в храмах Подмосковья." },
  { key: "06-28", name: "Прор. Амоса", kind: "saint", desc: "Св. пророк Амос, живший в VIII в. до Р.Х., был пастухом из колена Завулонова. Несмотря на простоту и необразованность, был избран Богом для обличения царя Иеровоама и отступившего от веры израильского народа." },
  { key: "06-28", name: "свт. Ионы, митрополита Московского и всея Руси, чудотворца", kind: "saint", desc: "Родился в Костромской земле. Ученик свт. Фотия. Стал первым автокефальным митрополитом, избранным в Москве (1448 г.), без утверждения Константинополя. Способствовал духовному единению Руси, укреплял власть московских князей." },
  { key: "06-28", name: "Свт. Михаила, первого митрополита Киевского", kind: "saint", desc: "Свт. Михаил (X в.) ‒ киевский митрополит, присланный из Константинополя в 988 году для крещения Руси. Родом сириец, он активно распространял христианство: строил храмы, назначал священников, уничтожал языческих идолов." },
  { key: "06-28", name: "мч. Дулы Киликийского", kind: "saint", desc: "Св. мч. Дула, христианин из Преториады, пострадал во время гонений императора Максимина (305-313 гг.). Представ перед правителем Максимом, он смело обличал язычество." },
  { key: "06-28", name: "прп. Дулы страстотерпца, Египетского", kind: "saint", desc: "Прп. Дула, египетский инок, 20 лет терпел насмешки братии, достигнув совершенного негневления. Когда церковные сосуды украли, его ложно обвинили, так как он отсутствовал на службе из-за болезни." },
  { key: "06-28", name: "прп. Иеронима Блаженного, Стридонского", kind: "saint", desc: "Прп. Иероним (ок. 347-420) – выдающийся христианский писатель и переводчик, создатель канонического латинского перевода Библии (Вульгаты). Родившись в Далмации, получил блестящее образование в Риме." },
  { key: "06-28", name: "Перенесение мощей прп. Феодора Сикеота, епископа Анастасиупольского", kind: "saint", desc: "Прп. Феодор Сикеот (VI-VII вв.) родился в Малой Азии. Он с детства был отмечен благодатью Божией. С 8 лет начал строгий пост, в 10 лет чудесно исцелился от смертельной болезни." },
  { key: "06-28", name: "блгв. кн. Сербского Лазаря", kind: "saint", desc: "Св. блгв. князь Лазарь Сербский (XIV в.) правил Сербией в тяжёлые времена турецкой угрозы. Приняв власть в 1371 г., он укреплял государство, защищал народ от грабежей, строил храмы и монастыри, добился признания Сербского Патриархата." },
  { key: "06-28", name: "свт. Ефрема II, патриарха Сербского", kind: "saint", desc: "Свт. Ефрем (1312-1400), 3-й патриарх Сербский, известный своей духовной мудростью и усилиями по укреплению Церкви в трудный период османского нашествия." },
  { key: "06-28", name: "блж. Августина, епископа Иппонийского", kind: "saint", desc: "Блж. Августин (354-430), епископ Иппонийский, родился в Северной Африке. Воспитанный христианкой Моникой, он долго искал истину, пока в Милане под влиянием свт." },
  { key: "06-28", name: "Собор преподобных отцов Псково-Печерских", kind: "feast", desc: "Собор Псково-Печерских святых – празднование Русской Православной Церкви в честь святых Псково-Печерской Успенской обители. Празднуется в 4 неделю по Пятидесятнице." },
  { key: "06-28", name: "Сщмч. Амоса Иванова, пресвитера", kind: "saint", desc: "Сщмч. Амос Иванов служил священником в Покровском храме посёлка Вахрушево в Енисейской губернии. В 1918-1919 гг., во время Гражданской войны, территория его служения стала ареной боевых действий между красными партизанами и войсками Колчака." },
  { key: "06-28", name: "Одигитрия Воронинская", year: "1518", kind: "saint", desc: "Явление Воронинской иконы Божией Матери произошло 15/28 июня 1518 года в 12 км к югу от Череповца на месте нынешнего погоста близ деревни Воронино. Пономарь церкви Архангела Михаила села Ильинское Иоанн пошел в Конечновский лес и, возвращая" },
  { key: "06-29", name: "Свт. Тихона, епископа Амафунтского", kind: "saint", desc: "Свт. Тихон Амафунтский (IV-V вв.) родился на Кипре в благочестивой семье. С юности прославился чудесами: по его молитве пустой амбар наполнился пшеницей, а сухие виноградные ветви дали плоды." },
  { key: "06-29", name: "прп. Тихона Медынского, Калужского", kind: "saint", desc: "Прп. Тихон Медынский (XV в.) ‒ основатель Тихоновой пустыни под Калугой. Уроженец Киева, принял постриг в Москве, затем удалился в лес, где жил в дупле дуба." },
  { key: "06-29", name: "прп. Тихона Луховского, Костромского, чудотворца", kind: "saint", desc: "Прп. Тихон Луховской (XV-XVI вв.) ‒ святой литовского происхождения. Будучи военным, оставил службу и переселился в Россию, избегая унии. Приняв монашество, основал пустынь в костромских землях, где подвизался в трудах и молитве." },
  { key: "06-29", name: "прп. Моисея Оптинского", kind: "saint", desc: "Прп. Моисей Оптинский (1782-1862), в миру Тимофей Путилов, родился в благочестивой купеческой семье. В юности вместе с братом ушел в Саровскую пустынь, где получил духовное руководство от прп." },
  { key: "06-29", name: "Перенесение мощей свт. Феофана, Затворника Вышенского", kind: "saint", desc: "Свт. Феофан Затворник (1815–1894) – выдающийся русский богослов, проповедник и духовный писатель. Окончив Киевскую Духовную Академию, принял монашество (1841), преподавал в СПДА, затем был направлен в Иерусалим, где изучал святые места и труды отцов Церкви.", lifeId: "feofan-zatvornik" },
  { key: "06-29", name: "Сщмчч. Гермогена (Долганева), епископа Тобольского,", kind: "saint", desc: "Свт. Гермоген (Долганев), епископ Тобольский, родился в 1858 году в семье священника. Окончил Санкт-Петербургскую духовную академию, принял монашество и служил в разных епархиях." },
  { key: "06-30", name: "Сщмч. Аверкия Северовостокова, пресвитера", kind: "saint", desc: "Сщмч. Аверкий Северовостоков (1845–1918) родился в семье священника, окончил Уфимскую духовную семинарию. В 1880 г. рукоположен во священника и назначен настоятелем Иоанно-Златоустовского храма в селе Емаши Уфимской губернии, где прослужил 38 лет." },
  { key: "06-30", name: "прп. Максима (Попова), исп., иеромонаха", kind: "saint", desc: "Прписп. Максим (Попов, 1876–1934) родился в благочестивой мордовской семье. В 1926 г. принял монашество и был рукоположен в иеромонаха. Служил в Сергиевском монастыре под Белебеем, а после его закрытия – в селе Рябаш, где возродил духовную жизнь." },
  { key: "06-30", name: "мц. Пелагии Балакиревой", kind: "saint", desc: "Мц. Пелагия Балакирева (1901-1943) родилась в крестьянской семье в Рязанской губернии. С 1927 г. работала сторожем, затем стала старостой Троицкой церкви в селе Шарапово." },
];
